create extension if not exists pgcrypto;

create table if not exists roles (id uuid primary key default gen_random_uuid(), code text unique not null check (code in ('ADMINISTRATIVE_EMPLOYEE','FIELD_INSPECTOR','PROTECTION_SAFETY_OFFICER','OPERATIONS_OFFICER')), name_ar text not null, created_at timestamptz not null default now());
create table if not exists app_users (id uuid primary key default gen_random_uuid(), auth_user_id uuid unique, display_name text not null default 'ABDULLA ALMAJED', employee_number text unique, email text unique, role_code text not null references roles(code), is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists facilities (id uuid primary key default gen_random_uuid(), facility_number text unique not null, facility_name text not null, owner_name text, personal_id text, registration_number text, phone_number text, governorate text, area text, block text, road text, building_number text, complex text, floors integer, fire_exits integer, hazardous_materials boolean not null default false, details text, status text not null default 'Active', created_by uuid references app_users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists facility_requirements (id uuid primary key default gen_random_uuid(), facility_id uuid not null references facilities(id) on delete cascade, requirement_key text not null, requirement_label text not null, requirement_section text not null, is_required boolean not null default true, created_at timestamptz not null default now(), unique(facility_id, requirement_key));
create table if not exists documents (id uuid primary key default gen_random_uuid(), facility_id uuid not null references facilities(id) on delete cascade, file_name text not null, document_type text not null, storage_path text not null, mime_type text, uploaded_by uuid references app_users(id), created_at timestamptz not null default now());
create table if not exists inspection_assignments (id uuid primary key default gen_random_uuid(), facility_id uuid not null references facilities(id), inspector_id uuid references app_users(id), assigned_by uuid references app_users(id), scheduled_at timestamptz, visit_type text not null default 'فحص أولي', status text not null default 'Assigned' check (status in ('Assigned','Accepted','En Route','Arrived','Inspection Started','Inspection Completed','Submitted')), instructions text, reassigned_from uuid references app_users(id), reassignment_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists inspections (id uuid primary key default gen_random_uuid(), report_number text unique not null, facility_id uuid not null references facilities(id), assignment_id uuid references inspection_assignments(id), inspector_id uuid references app_users(id), inspection_date timestamptz not null default now(), status text not null default 'Submitted', review_status text not null default 'Pending Review', inspector_notes text, officer_notes text, submitted_at timestamptz, reviewed_at timestamptz, reviewed_by uuid references app_users(id), created_at timestamptz not null default now());
create table if not exists inspection_results (id uuid primary key default gen_random_uuid(), inspection_id uuid not null references inspections(id) on delete cascade, inspection_key text not null, inspection_label text not null, selected_value text not null, notes text, photo_paths jsonb not null default '[]'::jsonb, is_violation boolean not null default false, created_at timestamptz not null default now());
create table if not exists violations (id uuid primary key default gen_random_uuid(), facility_id uuid not null references facilities(id), inspection_id uuid references inspections(id), violation_type text not null, title text not null, amount_bhd numeric(12,3) not null default 0, status text not null default 'Open' check (status in ('Open','Under Review','Due Soon','Overdue','Closed')), approval_date timestamptz, due_date timestamptz, payment_reference text, closed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists requirement_deficiencies (id uuid primary key default gen_random_uuid(), facility_id uuid not null references facilities(id), inspection_id uuid references inspections(id), requirement_key text not null, requirement_label text not null, inspection_key text, deficiency_status text not null default 'Open', notes text, photo_paths jsonb not null default '[]'::jsonb, created_at timestamptz not null default now(), resolved_at timestamptz);
create table if not exists tasks (id uuid primary key default gen_random_uuid(), title text not null, description text, assigned_to uuid references app_users(id), assigned_by uuid references app_users(id), facility_id uuid references facilities(id), status text not null default 'New' check (status in ('New','In Progress','Waiting','Completed')), due_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists reinspections (id uuid primary key default gen_random_uuid(), facility_id uuid not null references facilities(id), original_inspection_id uuid references inspections(id), assignment_id uuid references inspection_assignments(id), required_checks jsonb not null default '[]'::jsonb, status text not null default 'Scheduled', created_by uuid references app_users(id), created_at timestamptz not null default now());
create table if not exists audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references app_users(id), actor_role text, operation text not null, entity_type text not null, entity_id text, old_values jsonb, new_values jsonb, created_at timestamptz not null default now());
create table if not exists facility_history (id uuid primary key default gen_random_uuid(), facility_id uuid not null references facilities(id) on delete cascade, event_type text not null, title text not null, details text, actor_id uuid references app_users(id), created_at timestamptz not null default now());
create table if not exists notifications (id uuid primary key default gen_random_uuid(), recipient_id uuid references app_users(id), title text not null, body text not null, entity_type text, entity_id text, is_read boolean not null default false, created_at timestamptz not null default now());
create index if not exists facilities_search_idx on facilities (facility_name, personal_id, registration_number);
create index if not exists inspection_assignments_inspector_idx on inspection_assignments (inspector_id, status);
create index if not exists violations_facility_status_idx on violations (facility_id, status);
insert into roles (code, name_ar) values ('ADMINISTRATIVE_EMPLOYEE','الموظف الإداري'),('FIELD_INSPECTOR','المفتش الميداني'),('PROTECTION_SAFETY_OFFICER','ضابط الحماية والسلامة'),('OPERATIONS_OFFICER','ضابط العمليات') on conflict (code) do update set name_ar = excluded.name_ar;
